3. Implement the CSV downloader service:

```javascript
import Service from '@ember/service';
import { get } from '@ember/object';
import { inject as service } from '@ember/service';
import { A } from '@ember/array';
import CSVBuilder from 'csv-builder';
import { worker } from 'ember-cli-web-worker';

export default Service.extend({
  store: service(),

  async downloadCSV(modelName, queryParams) {
    const { store } = this;
    const records = await store.query(modelName, queryParams);

    const csvBuilder = new CSVBuilder({
      delimiter: ',',
      newline: '\n',
      wrap: true,
    });

    const headers = records[0] && Object.keys(get(records[0], 'attributes'));
    const rows = records.map((record) => {
      const row = {};
      headers.forEach((header) => {
        row[header] = get(record, 'attributes')[header];
      });
      return row;
    });

    const csv = csvBuilder.build({ headers, rows });

    this._super.performAction('downloadCSV', { csv });
  },

  _super: worker(({ csv }) => {
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `data.csv`;
    a.click();
    URL.revokeObjectURL(url);
  }),
});
