import org.springframework.batch.item.file.FlatFileItemReader;
import org.springframework.batch.item.file.mapping.FieldSetMapper;
import org.springframework.batch.item.file.transform.DelimitedLineTokenizer;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

import java.util.Map;

@Configuration
public class QueryFileReaderConfig {

    @Value("classpath:query.sql")
    private Resource queryResource;

    @Bean
    public FlatFileItemReader<Map<String, String>> queryFileItemReader() {
        FlatFileItemReader<Map<String, String>> reader = new FlatFileItemReader<>();
        reader.setResource(queryResource);
        reader.setLineMapper(new LineMapper<Map<String, String>>() {
            {
                setLineTokenizer(new DelimitedLineTokenizer() {
                    {
                        setNames(new String[]{"query"});
                    }
                });
                setFieldSetMapper(new FieldSetMapper<Map<String, String>>() {
                    @Override
                    public Map<String, String> mapFieldSet(FieldSet fieldSet) {
                        return fieldSet.getValues();
                    }
                });
            }

            @Override
            public Map<String, String> mapLine(String line, int lineNumber) throws Exception {
                return getLineTokenizer().tokenize(line);
            }
        });
        return reader;
    }
}
```

